import{_ as o,o as t,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"原型式继承","description":"道格拉斯 · 克罗克福在 2006 年提出了原型式继承（ prototypal inheritance in JavaScript ）。 就是把某个对象当成原型对象的继承方式，适合快速从已有对象获取属性和方法。 思路： 只想让 A 对象与 B 对象保持类似的情况下，没必要兴师动众。","frontmatter":{"title":"原型式继承","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"道格拉斯 · 克罗克福在 2006 年提出了原型式继承（ prototypal inheritance in JavaScript ）。 就是把某个对象当成原型对象的继承方式，适合快速从已有对象获取属性和方法。 思路： 只想让 A 对象与 B 对象保持类似的情况下，没必要兴师动众。","sidebarWeight":149,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(80m)继承/(10m)原型式继承.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)原型式继承.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)原型式继承.md"}'),n={name:"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)原型式继承.md"};function c(s,e,i,l,p,d){return t(),r("div",null,[...e[0]||(e[0]=[a('<div><h1 id="原型式继承" tabindex="-1">原型式继承 <a class="header-anchor" href="#原型式继承" aria-label="Permalink to &quot;原型式继承&quot;">​</a></h1><blockquote><p>本节目标：理解“原型式继承”的核心思路，并能把它用于实际开发或面试表达。 道格拉斯<code>·</code>克罗克福在<code>2006</code>年提出了原型式继承（<code>prototypal inheritance in JavaScript</code>）。</p></blockquote><p>就是把某个对象当成原型对象的继承方式，适合快速从已有对象获取属性和方法。</p><p>**思路：**只想让<code>A</code>对象与<code>B</code>对象保持类似的情况下，没必要兴师动众创建构造函数：</p><ol><li>定义一个临时构造函数；</li><li>让临时构造函数的原型指向<code>B</code>对象即可；</li><li>然后返回临时构造函数的实例，即<code>A</code>对象。</li></ol><p>代码如下： function createObject(o) { function F() {} F.prototype = o; return new F(); } const parent = { name: &#39;Parent&#39;, sayHello: function() { console.log(&#39;Hello from Parent&#39;); } }; const child = createObject(parent); console.log(child.name); // 输出: Parent child.sayHello(); // 输出: Hello from Parent</p><p>从本质上讲，<code>object()</code>对传入其中的对象执行了一次浅复制。看代码： var person = { name: &#39;Nicholas&#39;, firends: [&#39;Shelby&#39;, &#39;Court&#39;, &#39;Van&#39;] }; var anotherPerson = object(person); anotherPerson.name = &#39;Greg&#39;; anotherPerson.friends.push(&#39;Rob&#39;); var yetAnotherPerson = object(person); yetAnotherPerson.name = &#39;Linda&#39;; yetAnotherPerson.friends.push(&#39;Barbie&#39;); console.log(person.friends);//&#39;Shelby,Court,Van,Rob,Barbie&#39; <code>person.friends</code>属性，不仅<code>person</code>所有，而且也会被<code>anotherPerson</code>以及<code>yetAnotherPerson</code>共享，相当于又创建了<code>person</code>对象的两个副本。</p><p><strong>Object.create()</strong> ECMAScript5通过新增Object.create()方法规范了原型式继承。 参数： 第一个参数是用作新对象原型的对象； 第二个参数是（可选的）一个为新对象定义额外属性的对象。与Object.defineProperties()方法的第二个参数格式相同：</p><ul><li>每个属性都是通过自己的描述符定义的。</li><li>这种方式指定的任何属性都会覆盖原型对象上的同名属性。</li></ul><p>例如： var person = { name: &#39;Nicholas&#39;, firends: [&#39;Shelby&#39;, &#39;Court&#39;, &#39;Van&#39;] }; var anotherPerson = Object.create(person, { name: { value: &#39;Greg&#39; } }) console.log(anotherPerson.name);//&#39;Greg&#39;</p></div>',1)])])}const _=o(n,[["render",c]]);export{m as __pageData,_ as default};
